SELECT * FROM vault_item
WHERE owner_id = #{ownerId}

    AND deleted_at IS NULL


    AND folder_id = #{folderId}


    AND (title LIKE '%' || #{q} || '%' OR COALESCE(host,'') LIKE '%' || #{q} || '%'
         OR COALESCE(username,'') LIKE '%' || #{q} || '%' OR COALESCE(url,'') LIKE '%' || #{q} || '%')


    AND updated_at > #{since}

ORDER BY title

SELECT * FROM vault_item
WHERE owner_id = #{ownerId}

    AND updated_at > #{since}

ORDER BY updated_at
